      const a = k ? -2.3 + k * 2.39996 + (R() - 0.5) * 0.7 : -1.9 + (R() - 0.5) * 0.4;
      const d = k ? 0.36 + 0.26 * R() + (1 - x.n / most) * 0.2 : 0.22;
