    let h = "<b>" + esc(e.n) + "</b><span>" + esc(HOU[e.h].name) + " · " + (e.y || "year not found") + "</span><em>" + esc(who) + " — " + CREDIT[e.c] + "</em>";
    if (full) h += "<span>" + esc(KIND[e.k]) + "</span>" + (e.s.length ? "<span>Sources: " + e.s.map((i) => esc(D.sources[i])).join(", ") + "</span>" : "");
